// 测试用 schemastery 最小替身：支持本插件 Config 使用的 object/boolean/number
// 链式 API（default/step/min/max）与调用时校验，行为对齐生产 schemastery 的
// 契约面。真实环境由 DSH 通过 profile 的 require 上下文提供。
function chain(defs = {}) {
  const schema = function (input) {
    if (input === undefined) {
      if (defs.default === undefined) throw new TypeError('required value missing')
      return defs.default
    }
    if (defs.kind === 'number' && typeof input !== 'number') throw new TypeError('expected a number')
    if (defs.kind === 'boolean' && typeof input !== 'boolean') throw new TypeError('expected a boolean')
    if (defs.min !== undefined && input < defs.min) throw new TypeError(`value ${input} is below min ${defs.min}`)
    if (defs.max !== undefined && input > defs.max) throw new TypeError(`value ${input} is above max ${defs.max}`)
    return input
  }
  schema.default = (value) => chain({ ...defs, default: value })
  schema.step = () => schema
  schema.min = (value) => chain({ ...defs, min: value })
  schema.max = (value) => chain({ ...defs, max: value })
  return schema
}

module.exports = {
  object(shape) {
    const schema = function (input) {
      if (input === undefined || input === null) input = {}
      if (typeof input !== 'object' || Array.isArray(input)) throw new TypeError('expected an object')
      const out = {}
      for (const [key, field] of Object.entries(shape)) out[key] = field(input[key])
      return out
    }
    schema.shape = shape
    return schema
  },
  boolean: () => chain({ kind: 'boolean' }),
  number: () => chain({ kind: 'number' }),
  string: () => chain({ kind: 'string' }),
}